def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_c = sum(1 for a in opp if a == 'C')
    opp_d = n - opp_c
    last_me = me[-1]
    last_opp = opp[-1]

    if n < 8:
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        return 'C'

    window = 10 if n >= 10 else n
    recent = opp[-window:]
    recent_c = sum(1 for a in recent if a == 'C')
    recent_d = window - recent_c

    if recent_d >= window - 1:
        return 'D'
    if recent_c >= window - 1:
        return 'C'

    opp_rate = opp_c / n

    if n >= 95:
        if opp_rate > 0.85 and recent_c >= window - 2:
            return 'D'
        if recent_d >= window - 3:
            return 'D'
        return 'C'

    if n >= 88:
        if opp_rate > 0.8 and recent_c >= window - 2:
            if rng.random() < 0.7:
                return 'D'
            return 'C'

    if opp_rate <= 0.2:
        return 'D'

    if opp_rate >= 0.9 and n >= 15:
        if rng.random() < 0.12:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            streak = 0
            for a in reversed(opp):
                if a == 'D':
                    streak += 1
                else:
                    break
            if streak >= 3:
                if rng.random() < 0.25:
                    return 'C'
                return 'D'
            return 'D'
        return 'D'

    if last_me == 'D':
        if recent_c >= window - 1:
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        return 'C'

    if recent_d >= 3:
        if rng.random() < 0.4:
            return 'D'
        return 'C'

    if opp_rate > 0.55:
        return 'C'

    if n >= 25:
        last20 = opp[-20:]
        switches = 0
        for i in range(1, len(last20)):
            if last20[i] != last20[i - 1]:
                switches += 1
        if switches >= 10:
            return 'C' if rng.random() < 0.6 else 'D'

    if recent_c >= 2:
        return 'C'
    return 'D' if rng.random() < 0.6 else 'C'
